fn main() { // \
    let n: usize = std::env::args().nth(1).and_then(|s| s.trim().parse().ok()).unwrap_or(0); // \
    const BASE: u64 = 1_000_000_000; // \
    let mut a: Vec<u64> = vec![1]; // \
    let mut b: Vec<u64> = vec![1]; // \
    for _ in 0..n { // \
        let mut c: Vec<u64> = Vec::with_capacity(b.len() + 1); // \
        let mut carry = 0u64; // \
        for i in 0..b.len() { // \
            let s = b[i] + if i < a.len() { a[i] } else { 0 } + carry; // \
            c.push(s % BASE); // \
            carry = s / BASE; // \
        } // \
        if carry > 0 { c.push(carry); } // \
        a = b; // \
        b = c; // \
    } // \
    let mut out = format!("{}", a[a.len() - 1]); // \
    for i in (0..a.len() - 1).rev() { out.push_str(&format!("{:09}", a[i])); } // \
    println!("{}", out); // \
} // \
